// genuary25
// JAN. 14. (credit: Melissa Wiederrecht)
// Pure black and white. No gray.

let seed = Math.random() * 9999;
let mySize, margin;
let num;
let myGraphic;
let palette;
let layers = [];
let speed = 3;
let layer_num, layer_x, layer_y;
let offset = 0;

function setup() {
	// pixelDensity(4);
	randomSeed(seed);
	mySize = max(windowWidth, windowHeight) * 0.8;
	margin = mySize / 100;
	createCanvas(mySize, mySize, WEBGL);
	ortho(-width / 2, width / 2, -height / 2, height / 2, -5000, 5000);
	myGraphic = createGraphics(mySize / 2, mySize / 2);
	frontGraphic = createGraphics(mySize / 2, mySize / 2);
	palette = random(colorScheme).colors.concat();
	angleMode(DEGREES);
	num = int(random(1, 1));
	layer_num = num;
	layer_w = width / layer_num;
	layer_h = height / layer_num;
	for (let i = 0; i < layer_num; i++) {
		for (let j = 0; j < layer_num; j++) {
			layers.push(new makeLayer(i * layer_w, j * layer_h, layer_w, 0));
		}
	}
	background(random(palette));
}

function draw() {
	randomSeed(seed);
	orbitControl();
	background(random(palette));
	createmyGraphic();

	for (let l of layers) {
		l.run();
	}
	offset += 1;
}

function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("genuary-20250114", "png");
	}
}

// === Tab: makeLayer ===
class makeLayer {
	constructor(x, y, size, rotate) {
		this.x = x;
		this.y = y;
		this.size = size;
		this.rotate = rotate;
		this.settime();
		this.tog = 0;
		this.t = 0;
		this.t1 = 0;
		this.speed = int(random(1, 6));
	}

	display() {
		noStroke();
		texture(myGraphic);

		push();
		rotateX(frameCount / 5 * random([-1, 1]));
		rotateY(frameCount / 5 * random([-1, 1]));
		rotateZ(frameCount / 5 * random([-1, 1]));

		translate(-width * 0.5 + this.size / 2 + this.x, -height * 0.5 + this.size / 2 + this.y, 0);

		let lavaShape = int(random(3, 6));
		let torusD = this.size * 0.35;
		let lavaLight_n = int(random(12, 4));
		rect(torusD / random(10, 50)); // Changed from sphere to rect
		for (let i = 0; i < lavaLight_n; i++) {
			let lavaLight_s = this.size / random(12, 6);
			rotateX(random(TAU) + offset / 10);
			rotateY(random(TAU) + offset / 10);
			rotateZ(random(TAU) + offset / 10);
			this.updateRotate();
			push();
			translate(0, 0, i * lavaLight_s / lavaLight_n);
			rect(torusD / lavaLight_n * (lavaLight_n - i) * 2, 2, 2);
			torus(torusD / lavaLight_n * (lavaLight_n - i), lavaLight_s / lavaLight_n, 60, lavaShape);
			pop();
		}

		pop();

		for (let i = 0; i < 20; i++) {
			push();
			rotateX(frameCount / 5 * random([-1, 1]));
			rotateY(frameCount / 5 * random([-1, 1]));
			rotateZ(frameCount / 5 * random([-1, 1]));
			translate(random(-1, 1) * mySize / 2, random(-1, 1) * mySize / 2, random(-1, 1) * mySize / 2);
			rotateX(random(TAU));
			rotateY(random(TAU));
			rotateZ(random(TAU));
			rect(random(1, 5)); // Changed from sphere to rect
			pop();
		}

	}

	settime() {
		this.t = -int((map(speed, 1, 5, 100, 500)));
		this.t1 = map(speed, 1, 5, 500, 100);
	}

	updateRotate() {
		switch (int(random(6))) {
			case 0:
				rotateZ(-this.rotate / random([1, 0.5]));
				break;
			case 1:
				rotateZ(this.rotate / random([1, 0.5]));
				break;
			case 2:
				rotateZ(this.rotate);
				break;
			case 3:
				rotateZ(-this.rotate);
				break;
			case 4:
				rotateZ(this.rotate);
				break;
			case 5:
				rotateZ(this.rotate);
				break;
		}
	}

	update1() {
		if (this.t >= 0 && this.t < this.t1) {
			let easePar = norm(this.t, 0, this.t1 - 1);
			this.rotate = lerp(-90, 90, Easing.easeOutQuint(easePar));
		}
		if (this.t1 < this.t) {
			if (this.tog) this.tog = 0;
			else this.tog = 1;
			this.settime();
		}
		this.t += random([1, 2, 4]);
	}

	update3() {
		if (this.t >= 0 && this.t < this.t1) {
			var easePar = norm(this.t, 0, this.t1 - 1);
			this.rotate = lerp(-90, 90, Easing.easeOutCirc(easePar));
		}
		if (this.t1 < this.t) {
			if (this.tog) this.tog = 0;
			else this.tog = 1;
			this.settime();
		}
		this.t += random([1, 2, 4]);
	}

	update2() {
		if (this.t >= 0 && this.t < this.t1) {
			var easePar = norm(this.t, 0, this.t1 - 1);
			this.rotate = lerp(-90, 90, Easing.easeOutBack(easePar));
		}
		if (this.t1 < this.t) {
			if (this.tog) this.tog = 0;
			else this.tog = 1;
			this.settime();
		}
		this.t += random([1, 2, 4]);
	}

	run() {
		this.display();
		switch (int(random(3))) {
			case 0:
				this.update1();
				break;
			case 1:
				this.update2();
				break;
			case 2:
				this.update3();
				break;
		}
	}
}


