function createmyGraphic() {
	myGraphic.background(random(palette));
	myGraphic.strokeCap(SQUARE);
	myGraphic.stroke(random(palette));
	myGraphic.noFill();
	// myGraphic.drawingContext.setLineDash([10, 20, 30]);
	myGraphic.drawingContext.lineDashOffset = offset / 1;
	if (int(seed) % 2 == 0) {
		myGraphic.strokeWeight(myGraphic.height / random([1, 1, 2]));
		myGraphic.line(myGraphic.width / 2, myGraphic.height / 1, myGraphic.width / 2, 0);
	}
	if (int(seed) % 2 == 1) {
		myGraphic.strokeWeight(myGraphic.width / random([1, 1, 2]));
		myGraphic.line(myGraphic.width, myGraphic.height / 2, 0, myGraphic.height / 2);
	}
	drawRect(0, 0, myGraphic.width, myGraphic.height, myGraphic);
}

function drawRect(x, y, w, h, p) {
	// first draw a rectangle
	p.strokeCap(SQUARE);
	p.stroke(random(palette));
	p.strokeWeight(w / random([1, 2]));
	p.noFill();
	p.drawingContext.setLineDash([5, 10, 15]);
	p.drawingContext.lineDashOffset = offset / random([1, 2]);
	p.line(x, y + h / 2, x + w / 2, y + h / 2)

	// then figure out if we need to draw another
	let splitWidth = random(1) > 0.5;
	let splitWhere = random(0.1, 0.6);

	// if we're splitting the width
	if (splitWidth && w > myGraphic.width / random([5, 4, 6])) {
		drawRect(x, y, w * splitWhere, h, p);
		drawRect(x + (w * splitWhere), y, w * (1 - splitWhere), h, p);
	}
	// else if we're splitting the height
	else if (h > myGraphic.height / random([4, 8, 10])) {
		drawRect(x, y, w, h * splitWhere, p);
		drawRect(x, y + (h * splitWhere), w, h * (1 - splitWhere), p);
	}
}

// === Tab: Easing ===
class Easing {
	static easeInSine(x) {
		return 1 - Math.cos((x * Math.PI) / 2);
	}

	static easeOutSine(x) {
		return Math.sin((x * Math.PI) / 2);
	}

	static easeInOutSine(x) {
		return -(Math.cos(Math.PI * x) - 1) / 2;
	}

	static easeInQuad(x) {
		return x * x;
	}

	static easeOutQuad(x) {
		return 1 - (1 - x) * (1 - x);
	}

	static easeInOutQuad(x) {
		return x < 0.5 ? 2 * x * x : 1 - Math.pow(-2 * x + 2, 2) / 2;
	}

	static easeInCubic(x) {
		return x * x * x;
	}

	static easeOutCubic(x) {
		return 1 - Math.pow(1 - x, 3);
	}

	static easeInOutCubic(x) {
		return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
	}

	static easeInQuart(x) {
		return x * x * x * x;
	}

	static easeOutQuart(x) {
		return 1 - Math.pow(1 - x, 4);
	}

	static easeInOutQuart(x) {
		return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
	}

	static easeInQuint(x) {
		return x * x * x * x * x;
	}

	static easeOutQuint(x) {
		return 1 - Math.pow(1 - x, 5);
	}

	static easeInOutQuint(x) {
		return x < 0.5 ? 16 * x * x * x * x * x : 1 - Math.pow(-2 * x + 2, 5) / 2;
	}

	static easeInExpo(x) {
		return x === 0 ? 0 : Math.pow(2, 10 * x - 10);
	}

	static easeOutExpo(x) {
		return x === 1 ? 1 : 1 - Math.pow(2, -10 * x);
	}

	static easeInOutExpo(x) {
		return x === 0 ?
			0 :
			x === 1 ?
			1 :
			x < 0.5 ?
			Math.pow(2, 20 * x - 10) / 2 :
			(2 - Math.pow(2, -20 * x + 10)) / 2;
	}

	static easeInCirc(x) {
		return 1 - Math.sqrt(1 - Math.pow(x, 2));
	}

	static easeOutCirc(x) {
		return Math.sqrt(1 - Math.pow(x - 1, 2));
	}

	static easeInOutCirc(x) {
		return x < 0.5 ?
			(1 - Math.sqrt(1 - Math.pow(2 * x, 2))) / 2 :
			(Math.sqrt(1 - Math.pow(-2 * x + 2, 2)) + 1) / 2;
	}

	// バックイージングには追加のパラメータ（c1とc3）が必要です。
	static easeInBack(x) {
		const c1 = 1.70158;
		const c3 = c1 + 1;
		return c3 * x * x * x - c1 * x * x;
	}

	static easeOutBack(x) {
		var c1 = 1.70158;
		var c3 = c1 + 1;
		return 1 + c3 * Math.pow(x - 1, 3) + c1 * Math.pow(x - 1, 2);
	}

	static easeInOutBack(x) {
		var c1 = 1.70158;
		const c2 = c1 * 1.525;
		return x < 0.5 ?
			(Math.pow(2 * x, 2) * ((c2 + 1) * 2 * x - c2)) / 2 :
			(Math.pow(2 * x - 2, 2) * ((c2 + 1) * (x * 2 - 2) + c2) + 2) / 2;
	}
}

